// ── Helpers ─────────────────────────────────────────────────────────────────
function safe(v, fallback) {
  if (v === undefined || v === null) return fallback;
  const s = String(v);
  if (s.includes("{{") || s.includes("}}")) return fallback;
  return s;
}

function safeFloat(v, fallback) {
  const n = parseFloat(v);
  return isNaN(n) ? fallback : n;
}

// ── Metadatos del tweet ──────────────────────────────────────────────────────
let tweetId = "", tweetText = "", tweetDate = "", tweetUrl = "", strapiUrl = "";
let strapiTweetId = null;

try { const m = $('Loop Tweet x Tweet').item.json;
  tweetId   = m?.tweet_id   ?? "";
  tweetText = m?.tweet_text ?? "";
  tweetDate = m?.tweet_date ?? "";
  tweetUrl  = m?.tweet_url  ?? "";
  strapiUrl = m?.strapi_url ?? "";
} catch(_) {}

try {
  strapiTweetId = $('Guardar Tweet Raw').item.json?.data?.documentId ?? $('Guardar Tweet Raw').item.json?.data?.id ?? null;
} catch(_) {}


// ── Leer output del LLM ──────────────────────────────────────────────────────
const inputJson = $input.first().json;

let raw = inputJson?.text
   ?? inputJson?.output
   ?? inputJson?.content
   ?? "";

// ── Parsear JSON ─────────────────────────────────────────────────────────────
let parsed = null;
let parseError = null;

try {
  let c = String(raw)
    .replace(/```json\s*/gi, "")
    .replace(/```\s*/gi, "")
    .trim();

  c = c.replace(/\{\{[^}]*\}\}/g, '""');

  const s = c.indexOf("{");
  if (s > 0) c = c.substring(s);
  const e = c.lastIndexOf("}");
  if (e !== -1 && e < c.length - 1) c = c.substring(0, e + 1);

  parsed = JSON.parse(c);
} catch(e) {
  parseError = String(e.message);
}

if (parseError !== null || parsed === null) {
  return [{ json: {
    parse_error:     true,
    error_msg:       parseError ?? "null result",
    raw_snippet:     String(raw).substring(0, 300),
    tweet_id:        String(tweetId),
    strapi_url:      String(strapiUrl),
    strapi_tweet_id: strapiTweetId
  }}];
}

const items = Array.isArray(parsed?.items) ? parsed.items : [];

if (items.length === 0) {
  return [{ json: {
    sin_datos:       true,
    tweet_id:        String(tweetId),
    strapi_url:      String(strapiUrl),
    strapi_tweet_id: strapiTweetId
  }}];
}

// ── Retornar un item por paso ─────────────────────────────────────────────────
return items.map(item => {
  const estado = safe(item.estado_general, "desconocido");
  const isCerrado = (estado === "cerrado" || estado === "suspendido");

  return { json: {
    codigo_fuente:        safe(item.codigo_fuente, null),
    fecha_reporte:        safe(item.fecha_reporte, null) ?? tweetDate,
    estado_general:       estado,
    fuente:               "x_upfronterizos",
    mensaje_original:     safe(item.mensaje_original, tweetText),
    confianza_extraccion: safeFloat(item.confianza_extraccion, 0.4),
    origen_tipo:          "twitter_account",
    horario_apertura:     safe(item.horario_apertura, null),
    horario_cierre:       safe(item.horario_cierre, null),
    tipo_vehiculos:       isCerrado ? [] : (Array.isArray(item.tipo_vehiculos) ? item.tipo_vehiculos : []),
    motivo_estado:        safe(item.motivo_estado, null),
    fecha_vigencia_desde: safe(item.fecha_vigencia_desde, null),
    fecha_vigencia_hasta: safe(item.fecha_vigencia_hasta, null),
    es_programado:        item.es_programado === true,
    tweet_id:             String(tweetId),
    tweet_url:            String(tweetUrl),
    tweet_date:           String(tweetDate),
    strapi_url:           String(strapiUrl),
    strapi_tweet_id:      strapiTweetId
  }};
});

