const d = $('Loop Tweet x Tweet').item.json;
const text = d.tweet_text || "";

const blocks = text.split(/(?=Complejos? Fronterizos?|C\.\s*F\.?|Pasos? Fronterizos?)/i);
const results = [];
let foundAnyMatch = false;
let failedAnyBlock = false;

for (const block of blocks) {
  if (!/(Complejos? Fronterizos?|C\.\s*F\.?|Pasos? Fronterizos?)/i.test(block)) continue;

  const match = block.match(/(?:Complejos? Fronterizos?|C\.\s*F\.?|Pasos? Fronterizos?)\s+([A-Za-zÁÉÍÓÚáéíóúÑñ\s\-]+?)\s*[✅❌⛔]\s*(HABILITADO|CERRADO|NO HABILITADO|SUSPENDIDO)/i);

  if (match) {
    foundAnyMatch = true;

    let nombrePaso = match[1].trim();
    nombrePaso = nombrePaso.replace(/[\-]$/, "").trim();
    const codigo_fuente = nombrePaso.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/\s+/g, '-');

    const estadoStr = match[2].toUpperCase();
    let estado_general = "desconocido";
    if (estadoStr === "HABILITADO") estado_general = "abierto";
    else if (estadoStr.includes("CERRADO") || estadoStr.includes("NO HABILITADO")) estado_general = "cerrado";
    else if (estadoStr === "SUSPENDIDO") estado_general = "suspendido";

    let horario_apertura = null;
    let horario_cierre = null;
    const horaMatch = block.match(/(\d{1,2}:\d{2})\s*[a-zA-Z]*\s*a\s*(\d{1,2}:\d{2})/i);
    if (horaMatch) {
      horario_apertura = horaMatch[1];
      horario_cierre = horaMatch[2];
    }

    let tipo_vehiculos = [];
    if (estado_general === "cerrado" || estado_general === "suspendido") {
      tipo_vehiculos = []; // Si está cerrado o suspendido, no hay vehículos
    } else {
      const tLower = block.toLowerCase();
      if (tLower.includes("todo tipo") || tLower.includes("todos los veh")) {
        tipo_vehiculos = ["automóvil", "bus", "camión"];
      } else {
        if (tLower.includes("bus ") || tLower.includes("buses")) tipo_vehiculos.push("bus");
        if (tLower.includes("menor") || tLower.includes("auto") || tLower.includes("particular")) tipo_vehiculos.push("automóvil");
        if (tLower.includes("carga") || tLower.includes("cami")) tipo_vehiculos.push("camión");
      }
      tipo_vehiculos = [...new Set(tipo_vehiculos)];
    }

    results.push({ json: {
      use_llm: false,
      codigo_fuente: codigo_fuente,
      fecha_reporte: d.tweet_date,
      estado_general: estado_general,
      fuente: "x_upfronterizos",
      mensaje_original: text,
      confianza_extraccion: 1.0,
      origen_tipo: "twitter_account",
      horario_apertura: horario_apertura,
      horario_cierre: horario_cierre,
      tipo_vehiculos: tipo_vehiculos,
      motivo_estado: null,
      fecha_vigencia_desde: null,
      fecha_vigencia_hasta: null,
      es_programado: false,
      tweet_id: String(d.tweet_id),
      tweet_url: String(d.tweet_url),
      tweet_date: String(d.tweet_date),
      strapi_url: String(d.strapi_url),
      strapi_tweet_id: $('Guardar Tweet Raw').item.json?.data?.documentId ?? $('Guardar Tweet Raw').item.json?.data?.id ?? null
    }});
  } else {
    failedAnyBlock = true;
  }
}

if (!foundAnyMatch || failedAnyBlock) {
  return [{ json: { use_llm: true } }];
}

return results;

